"""Self-contained XGBoost solution. Change this file; use evaluate.py to test."""
import numpy as np
import pandas as pd
import xgboost as xgb

PARAMS = {"n_estimators": 300, "max_depth": 2, "learning_rate": 0.03}
CONFIG = {
    "cat_mode": "native",      # native | ordinal | drop  (handling of string columns)
    "drop": [],                # raw columns removed from the matrix
    "fe": [],                  # engineered feature groups
    "unrecorded_to_nan": False,  # review counters -> NaN when plan-review days are absent
    "recency_weight": 0.0,     # extra weight on rows from the plan-review-recorded regime
}
CATS = ["permitclass", "permitclassmapped", "permittypedesc", "originalzip"]


def _num(X, c):
    return pd.to_numeric(X[c], errors="coerce").to_numpy(dtype=float)


def _features(X, cfg):
    out = {}
    fe = cfg["fe"]
    td = _num(X, "totaldaysplanreview")
    nrc = _num(X, "numberreviewcycles")
    doc = _num(X, "daysoutcorrections")
    a2i = _num(X, "applied_to_issued_days")
    cost = _num(X, "estprojectcost")
    hu = _num(X, "housingunits")
    hua = _num(X, "housingunitsadded")
    if cfg["unrecorded_to_nan"]:
        unrec = np.isnan(td) & (nrc == 0)
        nrc = np.where(unrec, np.nan, nrc)
        doc = np.where(unrec & (doc == 0), np.nan, doc)
    for c in X.columns:
        if c in CATS or c in cfg["drop"]:
            continue
        out[c] = _num(X, c)
    if "numberreviewcycles" in out:
        out["numberreviewcycles"] = nrc
    if "daysoutcorrections" in out:
        out["daysoutcorrections"] = doc
    if "review" in fe:
        out["review_gap"] = a2i - td
        out["days_per_cycle"] = td / np.where(nrc > 0, nrc, np.nan)
        out["out_frac"] = doc / np.where(td > 0, td, np.nan)
        out["city_days"] = td - doc
    if "anyreview" in fe:
        out["wait_best"] = np.where(np.isnan(td), a2i, td)
    if "cost" in fe:
        out["log_cost"] = np.log10(np.maximum(cost, 1.0))
        out["cost_per_unit"] = cost / np.where(hu > 0, hu, np.nan)
        out["cost_round"] = (cost % 1000 == 0).astype(float) + (cost % 10000 == 0) + (cost % 100000 == 0)
    if "month" in fe:
        s = _num(X, "issue_month_sin")
        co = _num(X, "issue_month_cos")
        out["month"] = np.round((np.degrees(np.arctan2(s, co)) % 360) / 30.0) % 12 + 1
    if "nrc_missing" in fe:
        out["nrc_missing"] = np.isnan(_num(X, "numberreviewcycles")).astype(float)
    return out


def prepare(state, X):
    cfg = state["cfg"]
    out = _features(X, cfg)
    df = pd.DataFrame(out, index=X.index)
    for c, lv in state["levels"].items():
        if cfg["cat_mode"] == "native":
            df[c] = pd.Categorical(X[c].astype(object), categories=lv)
        elif cfg["cat_mode"] == "ordinal":
            df[c] = pd.Categorical(X[c].astype(object), categories=lv).codes.astype(float)
            df.loc[df[c] < 0, c] = np.nan
    return df[state["cols"]]


def fit(X_train, y_train, *, seed, threads):
    cfg = dict(CONFIG)
    X_train = X_train.copy()
    y = np.asarray(y_train)
    levels = {}
    if cfg["cat_mode"] != "drop":
        for c in CATS:
            if c in cfg["drop"] or c not in X_train:
                continue
            if cfg["cat_mode"] == "ordinal":
                # order levels by training frequency (label-free), so codes carry no target information
                vc = X_train[c].dropna().astype(object).value_counts()
                levels[c] = pd.Index(sorted(vc.index, key=lambda k: (-vc[k], str(k))))
            else:
                levels[c] = pd.Index(sorted(X_train[c].dropna().astype(object).unique(), key=str))
    state = {"cfg": cfg, "levels": levels, "cols": None}
    cols = list(_features(X_train.iloc[:5], cfg).keys()) + list(levels.keys())
    state["cols"] = cols
    Z = prepare(state, X_train)
    w = None
    if cfg["recency_weight"] > 0:
        rec = X_train["totaldaysplanreview"].notna().to_numpy()
        w = 1.0 + cfg["recency_weight"] * rec
    m = xgb.XGBClassifier(tree_method="hist", enable_categorical=True, random_state=seed, n_jobs=threads, **PARAMS)
    m.fit(Z, y, sample_weight=w)
    state["model"] = m
    return state

