# against a random-halves noise ceiling. Validation shown for reference only.
from common import *
from scipy.stats import spearmanr
import warnings; warnings.filterwarnings('ignore')
d=pd.to_datetime(tr.issueddate); A=tr[d<'2018']; B=tr[d>='2018']
def bins(col,ref):
    x=ref[col]
    if x.dtype==object or x.nunique()<=12: return None
    q=np.unique(np.nanquantile(x,np.linspace(0,1,9)[1:-1])); return q
def rates(df,col,q):
    g=df[col].fillna(-9e9) if q is not None else df[col].astype(object).fillna('NA').astype(str)
    if q is not None: g=np.where(df[col].isna(),-1,np.searchsorted(q,df[col].fillna(0)))
    return df.groupby(g)[T].agg(['mean','size'])
def corr(a,b,col,q,minn=60):
    x=rates(a,col,q); y=rates(b,col,q); j=x.join(y,lsuffix='_a',rsuffix='_b',how='inner'); j=j[(j.size_a>=minn)&(j.size_b>=minn)]
    if len(j)<3: return np.nan,len(j)
    return spearmanr(j.mean_a,j.mean_b)[0],len(j)
rng=np.random.default_rng(0); out=[]
for c in FEATS:
    q=bins(c,tr); s,n=corr(A,B,c,q); v,_=corr(tr,ev,c,q)
    r=[]
    for _ in range(40):
        m=rng.random(len(tr))<0.5; r.append(corr(tr[m],tr[~m],c,q)[0])
    out.append((c,n,s,np.nanmean(r),v))
