    if str(A[c].dtype)=='category':
        na_a,na_b=A[c].isna().mean(),B[c].isna().mean()
        if na_b>na_a+0.01 or (na_a==0 and na_b>0): print(f'  {c}: unmatched-level share train {na_a:.4f} validation {na_b:.4f}')
