    na_a,na_b=A[c].isna().mean(),B[c].isna().mean()
    msg=[]
    if out: msg.append(f'{out} validation values outside training range [{a.min():.4g}, {a.max():.4g}]')
    if unseen: msg.append(f'unseen values {unseen[:5]}')
